```python
import re

_ALLOWED = re.compile(r"[\d\s()+\-]+")


def _parse(raw: str) -> str:
    """Оставить только цифры, проверив тип и допустимые символы."""
    if not isinstance(raw, str):
        raise ValueError("номер должен быть строкой")
    if not _ALLOWED.fullmatch(raw):
        raise ValueError("недопустимые символы в номере")
    stripped = raw.strip()
    if "+" in stripped:
        if not stripped.startswith("+") or stripped.count("+") > 1:
            raise ValueError("'+' допустим только в начале номера")
    digits = re.sub(r"\D", "", raw)
    if not digits:
        raise ValueError("во входе нет цифр")
    return digits


def _leading_kind(digits: str) -> str:
    """Вернуть '8', '7' или 'none' — тип ведущей цифры."""
    if digits[0] == "8":
        return "8"
    if digits[0] == "7":
        return "7"
    if len(digits) == 11:
        raise ValueError("11-значный номер должен начинаться с 8 или 7")
    return "none"


def normalize_phone(raw: str) -> str:
    """Привести российский номер к виду +7XXXXXXXXXX."""
    digits = _parse(raw)
    if _leading_kind(digits) in ("8", "7"):
        digits = digits[1:]
    if len(digits) != 10:
        raise ValueError(
            f"ожидалось 10 цифр национального номера, получено {len(digits)}"
        )
    return "+7" + digits
```

Логика: снимаем ведущую 8/7, дальше требуем ровно 10 цифр национального номера и клеим `"+7" + 10 цифр`. Неверный тип, недопустимые символы, пустой ввод и неверная длина → `ValueError`.

